'use client';

import { reportError } from '@/lib/api';

import React, { useState, useEffect } from 'react';
import UniversalSearch from '@/components/shared/UniversalSearch';
import { useTranslations } from 'next-intl';
import Link from 'next/link';
import DashboardTimeline from './DashboardTimeline';
import TimelineSettingsSlideOver, { DEFAULT_ENABLED_EVENTS, EventType } from './TimelineSettingsSlideOver';
import PinnedReportWidget from './PinnedReportWidget';
import ReportSettingsSlideOver from './ReportSettingsSlideOver';
import { userSettingsControllerGetSettings, userSettingsControllerUpdateSettings, businessReportsControllerGetReports } from '@modbm/sdk';

export default function DashboardContent() {
  const t = useTranslations('dashboard');
  const tTimeline = useTranslations('dashboard.timeline');
  const [isTimelineSettingsOpen, setIsTimelineSettingsOpen] = useState(false);
  const [isReportSettingsOpen, setIsReportSettingsOpen] = useState(false);
  const [enabledEvents, setEnabledEvents] = useState<EventType[]>(DEFAULT_ENABLED_EVENTS);
  const [isLoaded, setIsLoaded] = useState(false);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [dashboardConfig, setDashboardConfig] = useState<Record<string, any> | null>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [userSettings, setUserSettings] = useState<Record<string, any> | null>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [reports, setReports] = useState<{ slug: string; name: string }[]>([]);

  useEffect(() => {
    Promise.all([
      userSettingsControllerGetSettings(),
      businessReportsControllerGetReports()
    ]).then(([settingsRes, reportsRes]) => {
      const settings = settingsRes.data;
      setUserSettings(settings);
      setDashboardConfig(settings.dashboardConfig || {});
      if (settings.dashboardConfig?.timelineEvents) {
        setEnabledEvents(settings.dashboardConfig?.timelineEvents as EventType[]);
      } else {
        setEnabledEvents(DEFAULT_ENABLED_EVENTS);
      }
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      setReports(((reportsRes as unknown as Record<string, any>).data as { slug: string; name: string }[]) || (reportsRes as unknown as { slug: string; name: string }[]));
      setIsLoaded(true);
    }).catch((err: unknown) => {
      reportError(err, 'DashboardContent');
      setIsLoaded(true);
    });
  }, []);

  const handlePreferencesChange = (events: EventType[]) => {
    setEnabledEvents(events);
    const updatedConfig = { ...dashboardConfig, timelineEvents: events };
    setDashboardConfig(updatedConfig);
    try {
      userSettingsControllerUpdateSettings({ dashboardConfig: updatedConfig }).catch(console.warn);
    } catch (err) {
      console.warn('Failed to save timeline preferences', err);
    }
  };

  const handlePinnedReportsChange = (newPinnedReports: { slug: string; configId: string; name?: string }[]) => {
    const updatedConfig = { ...dashboardConfig, pinnedReports: newPinnedReports };
    setDashboardConfig(updatedConfig);
    try {
      userSettingsControllerUpdateSettings({ dashboardConfig: updatedConfig }).catch(console.warn);
    } catch (err) {
      console.warn('Failed to save pinned reports preferences', err);
    }
  };

  return (
    <>
      <div className="p-8 h-full overflow-y-auto lg:overflow-x-hidden">
        <div className="max-w-6xl mx-auto">
          <h2 className="text-2xl font-bold mb-8">{t('title')}</h2>
          
          <div className="mb-12">
            <UniversalSearch />
          </div>

          <div className="flex flex-col gap-12">
            {(Object.keys(userSettings?.reportConfigs || {}).length > 0 || dashboardConfig?.pinnedReports?.length > 0) && (
              <div className="w-full">
                <div className="flex items-center justify-between mb-6 border-b pb-4" style={{ borderColor: 'var(--border)' }}>
                  <div className="flex items-center gap-2 text-[11px] font-bold uppercase tracking-[0.1em] opacity-50" style={{ color: 'var(--text-primary)' }}>
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined text-[16px]">push_pin</span>
                    {t('pinnedReports')}
                  </div>
                  <button 
                    onClick={() => setIsReportSettingsOpen(true)}
                    className="w-8 h-8 rounded-lg flex items-center justify-center hover:bg-black/5 dark:hover:bg-white/5 transition-colors group"
                    title={t('managePinnedReports')}
                  >
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined text-[18px] text-[var(--accent)] group-hover:rotate-90 transition-transform duration-300">settings</span>
                  </button>
                </div>
                
                {(!dashboardConfig?.pinnedReports || dashboardConfig.pinnedReports.length === 0) ? (
                  <div className="text-center p-8 border border-dashed rounded-xl opacity-50 text-[14px]">
                    {t('noPinnedReports')}
                  </div>
                ) : (
                  <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                    {dashboardConfig?.pinnedReports?.map((report: { slug: string; configId: string; name?: string }, idx: number) => (
                      <PinnedReportWidget key={idx} slug={report.slug} configId={report.configId} name={report.name} />
                    ))}
                  </div>
                )}
              </div>
            )}

            <div className="w-full">
              <div className="flex items-center gap-2 mb-6 border-b pb-4 text-[11px] font-bold uppercase tracking-[0.1em] opacity-50" style={{ color: 'var(--text-primary)', borderColor: 'var(--border)' }}>
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="material-symbols-outlined text-[16px]">bolt</span>
                {t('quickActions.title')}
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <Link
                  href="/sales-orders/new"
                  className="group p-6 rounded-2xl transition-all duration-300 hover:scale-[1.02] hover:shadow-lg border flex flex-col gap-5 cursor-pointer no-underline"
                  style={{
                    background: 'var(--bg-card)',
                    borderColor: 'var(--border)',
                  }}
                >
                  <div 
                    className="w-12 h-12 rounded-xl flex items-center justify-center transition-colors duration-300 group-hover:scale-110"
                    style={{ background: 'rgba(0, 107, 92, 0.08)' }}
                  >
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined text-2xl" style={{ color: 'var(--accent)' }}>receipt_long</span>
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="font-bold text-[15px] group-hover:text-accent transition-colors" style={{ color: 'var(--text-primary)' }}>
                      {t('quickActions.createSalesOrder')}
                    </div>
                    <div className="text-[13px] opacity-60 mt-0.5 truncate" style={{ color: 'var(--text-muted)' }}>
                      {t('quickActions.createSalesDesc')}
                    </div>
                  </div>
                </Link>

                <Link
                  href="/purchase-orders/new"
                  className="group p-6 rounded-2xl transition-all duration-300 hover:scale-[1.02] hover:shadow-lg border flex flex-col gap-5 cursor-pointer no-underline"
                  style={{
                    background: 'var(--bg-card)',
                    borderColor: 'var(--border)',
                  }}
                >
                  <div 
                    className="w-12 h-12 rounded-xl flex items-center justify-center transition-colors duration-300 group-hover:scale-110"
                    style={{ background: 'rgba(0, 107, 92, 0.08)' }}
                  >
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined text-2xl" style={{ color: 'var(--accent)' }}>local_shipping</span>
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="font-bold text-[15px] group-hover:text-accent transition-colors" style={{ color: 'var(--text-primary)' }}>
                      {t('quickActions.createPurchaseOrder')}
                    </div>
                    <div className="text-[13px] opacity-60 mt-0.5 truncate" style={{ color: 'var(--text-muted)' }}>
                      {t('quickActions.createPurchaseDesc')}
                    </div>
                  </div>
                </Link>
              </div>
            </div>

            <div className="w-full flex flex-col">
              <div className="flex items-center justify-between mb-6 border-b pb-4" style={{ borderColor: 'var(--border)' }}>
                <div className="flex items-center gap-2 text-[11px] font-bold uppercase tracking-[0.1em] opacity-50" style={{ color: 'var(--text-primary)' }}>
                  {/* eslint-disable-next-line i18next/no-literal-string */}
                  <span className="material-symbols-outlined text-[16px]">history</span>
                  {tTimeline('title')}
                </div>
                
                <button 
                  onClick={() => setIsTimelineSettingsOpen(true)}
                  className="w-8 h-8 rounded-lg flex items-center justify-center hover:bg-black/5 dark:hover:bg-white/5 transition-colors group"
                  title={tTimeline('settings')}
                >
                  {/* eslint-disable-next-line i18next/no-literal-string */}
                  <span className="material-symbols-outlined text-[18px] text-[var(--accent)] group-hover:rotate-90 transition-transform duration-300">settings</span>
                </button>
              </div>

              <div className="flex-1 min-h-[400px]">
                {isLoaded && <DashboardTimeline enabledEvents={enabledEvents} />}
              </div>
            </div>
          </div>
        </div>
      </div>

      {isLoaded && (
        <>
          <TimelineSettingsSlideOver 
            isOpen={isTimelineSettingsOpen}
            onClose={() => setIsTimelineSettingsOpen(false)}
            enabledEvents={enabledEvents}
            onChange={handlePreferencesChange}
          />
          <ReportSettingsSlideOver
            isOpen={isReportSettingsOpen}
            onClose={() => setIsReportSettingsOpen(false)}
            reportConfigs={userSettings?.reportConfigs || {}}
            pinnedReports={dashboardConfig?.pinnedReports || []}
            reports={reports}
            onChange={handlePinnedReportsChange}
          />
        </>
      )}
    </>
  );
}

'use client';

import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { useState, useEffect, useMemo } from 'react';
import * as api from '@modbm/sdk';
import { toast } from 'react-hot-toast';
import { useRouter } from 'next/navigation';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import PageNav from '@/components/shared/PageNav';
import { InlineSettingsTable } from '@/components/shared/InlineSettingsTable';
import { useTranslations } from 'next-intl';
import { getErrorMessage } from '@modbm/shared';
import { reportError } from '@/lib/api';

// ── Types ────────────────────────────────────────────────────────────────────

interface ApiKey {
  apiKeyId: string;
  name: string;
  prefix: string;
  role: string;
  createdOn: string;
}

interface Webhook {
  webhookId: string;
  targetUrl: string;
  eventTypes: string[];
  isActive: boolean;
  secretKey: string;
  createdOn: string;
}

export default function DevelopersPage() {
  useDocumentTitle('Developers');
  const tCommon = useTranslations('admin.common');
  const tDev = useTranslations('admin.developers');
  const router = useRouter();

  // ── Rate Limits State ───────────────────────────────────────────────────────
  const [appForm, setAppForm] = useState<Partial<api.AppConfigResponseDto>>({});
  const [appLoading, setAppLoading] = useState(true);

  // ── API Keys State ──────────────────────────────────────────────────────────
  const [apiKeys, setApiKeys] = useState<ApiKey[]>([]);
  const [keysLoading, setKeysLoading] = useState(true);
  const [newSecret, setNewSecret] = useState<string | null>(null);
  const [roles, setRoles] = useState<api.RoleDetailsDto[]>([]);

  // ── Webhooks State ──────────────────────────────────────────────────────────
  const [webhooks, setWebhooks] = useState<Webhook[]>([]);
  const [webhooksLoading, setWebhooksLoading] = useState(true);
  const [availableEvents, setAvailableEvents] = useState<string[]>([]);

  // ── Data Loading ────────────────────────────────────────────────────────────

  const loadAppConfig = async () => {
    try {
      setAppLoading(true);
      const res = await api.appConfigControllerGet();
      setAppForm(res.data || {});
    } catch (err: unknown) {
      toast.error('Failed to load settings: ' + getErrorMessage(err));
    } finally {
      setAppLoading(false);
    }
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const updateAppField = async (field: string, value: any) => {
    try {
      setAppForm((prev: unknown) => ({ ...((prev as Record<string, unknown>) || {}), [field]: value }));
      await api.appConfigControllerUpdate({ [field]: value });
      toast.success('Updated successfully');
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  const loadKeys = async () => {
    try {
      setKeysLoading(true);
      const res = await api.apiKeysControllerList();
      setApiKeys((res.data as ApiKey[]) || []);
    } catch (err: unknown) {
      toast.error('Failed to load API keys: ' + (err as Error).message);
    } finally {
      setKeysLoading(false);
    }
  };

  const loadWebhooks = async () => {
    try {
      setWebhooksLoading(true);
      const res = await api.webhooksControllerList();
      setWebhooks((res.data as Webhook[]) || []);
    } catch (err: unknown) {
      toast.error('Failed to load Webhooks: ' + (err as Error).message);
    } finally {
      setWebhooksLoading(false);
    }
  };

  const loadRoles = async () => {
    try {
      const res = await api.rolesControllerFindAll();
      setRoles((res.data as api.RoleDetailsDto[]) || []);
    } catch (err: unknown) {
      reportError(err, 'DevelopersPage_loadRoles');
      toast.error('Failed to load roles: ' + getErrorMessage(err));
    }
  };

  const loadEvents = async () => {
    try {
      const res = await api.webhooksControllerListEvents();
      setAvailableEvents(res.data as string[] || []);
    } catch (err: unknown) {
      reportError(err, 'DevelopersPage_loadEvents');
    }
  };

  useEffect(() => {
    loadAppConfig();
    loadKeys();
    loadWebhooks();
    loadRoles();
    loadEvents();
  }, []);

  // ── Handlers ───────────────────────────────────────────────────────────────



  const navSections = useMemo(() => [
    { id: 'rate-limits', label: 'Rate Limits', show: true },
    { id: 'api-keys', label: 'API Keys', show: true },
    { id: 'webhooks', label: 'Webhooks', show: true },
  ], []);

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title="Developers"
          subtitle="Manage API access, webhooks, and rate limits"
          onBack={() => router.push('/admin')}
          actions={<PageNav sections={navSections} />}
          showPrint={false}
        />
      }
    >
      <div className="flex flex-col gap-6">
        {/* ── Rate Limits ────────────────────────────────────────────────── */}
        <div id="rate-limits" className="card">
          <h3 className="section-heading mb-4">
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined">speed</span>
            {tDev('apiRateLimits')}
          </h3>
          <div className="flex flex-col gap-1 max-w-sm">
            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
              {tDev('maxRequestsPerMinute')}
            </label>
            <input
              type="number"
              className="input"
              value={appForm?.apiRateLimit || ''}
              onChange={(e) => setAppForm({ ...(appForm || {}), apiRateLimit: e.target.value })}
              onBlur={(e) => updateAppField('apiRateLimit', e.target.value || '1000')}
              placeholder="1000"
              disabled={appLoading}
            />

          </div>
        </div>

        {/* ── API Keys ───────────────────────────────────────────────────── */}
        <div id="api-keys" className="card relative">
          <h3 className="section-heading mb-4">
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined">key</span>
            {tDev('apiKeys')}
          </h3>
          <InlineSettingsTable
            data={apiKeys || []}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            rowKey={(r: any) => r.apiKeyId}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            onSave={async (row: any, isNew: boolean) => {
              if (isNew) {
                const res = await api.apiKeysControllerCreate({ name: row.name, role: row.role });
                setNewSecret(res.data.secretKey);
                toast.success('API Key created');
                await loadKeys();
              }
            }}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            onDelete={async (row: any) => {
              if (!confirm('Are you sure you want to revoke this API key?')) return;
              await api.apiKeysControllerRevoke(row.apiKeyId);
              toast.success('API Key revoked');
              await loadKeys();
            }}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            onAdd={() => ({ name: '', role: 'agent', prefix: 'Will be generated...', createdOn: new Date().toISOString() } as any)}
            canEdit={() => false}
            canDelete={() => true}
            addLabel={tDev('createKey')}
            emptyLabel={tDev('noApiKeysFound')}
            columns={[
              {
                key: 'name',
                title: tCommon('name'),
                type: 'text',
                validate: (v) => v ? null : 'Required'
              },
              {
                key: 'role',
                title: 'Role',
                type: 'select',
                options: [
                  { value: 'agent', label: tDev('roleAgent') },
                  { value: 'webhook', label: tDev('roleWebhook') },
                  { value: 'viewer', label: tDev('roleViewer') },
                  { value: 'admin', label: tDev('roleAdmin') },
                  ...roles
                    .filter(r => !['agent', 'webhook', 'viewer', 'admin'].includes(r.role))
                    .map(r => ({ value: r.role, label: `${r.role} ${tDev('customRoleSuffix')}` }))
                ]
              },
              {
                key: 'prefix',
                title: tCommon('prefix'),
                type: 'text',
                disabled: true
              },
              {
                key: 'createdOn',
                title: tCommon('created'),
                type: 'custom',
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                render: (row: any) => <span>{new Date(row.createdOn).toLocaleDateString()}</span>
              }
            ]}
          />

          {/* New API Key Secret Modal */}
          {newSecret && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4">
              <div className="bg-[var(--bg-card)] rounded-lg shadow-2xl max-w-lg w-full p-6 border border-[var(--border)] relative">
                <h3 className="text-xl font-bold mb-2 flex items-center gap-2 text-[var(--warning)]">
                  {/* eslint-disable-next-line i18next/no-literal-string */}
                  <span className="material-symbols-outlined text-[24px]">warning</span>
                  {tDev('copyApiKeyWarning')}
                </h3>
                <p className="text-sm text-muted mb-6">
                  {tDev('onlyTimeSecretShown')}
                </p>
                <div className="flex items-center gap-2 mb-8">
                  <code className="p-4 rounded bg-black/5 text-[var(--text-primary)] font-mono flex-1 text-center border border-[var(--border)] text-lg tracking-wider select-all break-all">{newSecret}</code>
                </div>
                <div className="flex justify-end gap-3 border-t border-[var(--border)] pt-4">
                  <button
                    className="btn btn-secondary"
                    onClick={() => setNewSecret(null)}
                  >
                    {tCommon('close')}
                  </button>
                  <button
                    className="btn btn-primary bg-[var(--warning)] hover:brightness-110 border-none text-black"
                    onClick={() => {
                      navigator.clipboard.writeText(newSecret);
                      toast.success(tCommon('copiedToClipboard'));
                    }}
                  >
                    {tCommon('copy')}
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* ── Webhooks ───────────────────────────────────────────────────── */}
        <div id="webhooks" className="card">
          <h3 className="section-heading mb-4">
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined">webhook</span>
            {tDev('webhooks')}
          </h3>
          <InlineSettingsTable
            data={webhooks || []}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            rowKey={(r: any) => r.webhookId}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            onSave={async (row: any, isNew: boolean) => {
              if (isNew) {
                await api.webhooksControllerCreate({
                  targetUrl: row.targetUrl,
                  eventTypes: (row.eventTypes || '').split(',').map((s: string) => s.trim()).filter(Boolean),
                });
                toast.success('Webhook created');
                await loadWebhooks();
              }
            }}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            onDelete={async (row: any) => {
              if (!confirm('Are you sure you want to delete this webhook?')) return;
              await api.webhooksControllerRemove(row.webhookId);
              toast.success('Webhook deleted');
              await loadWebhooks();
            }}
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            onAdd={() => ({ targetUrl: '', eventTypes: '', secretKey: tDev('autoGenerated') } as any)}
            canEdit={() => false}
            canDelete={() => true}
            addLabel={tDev('addWebhook')}
            emptyLabel={tDev('noWebhooksFound')}
            columns={[
              {
                key: 'targetUrl',
                title: tDev('targetUrl'),
                type: 'text',
                validate: (v) => v ? null : 'Required'
              },
              {
                key: 'eventTypes',
                title: tDev('events'),
                type: 'text',
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                render: (row: any, isEditing: boolean, onChange?: (val: any) => void) => {
                  const currentEvents = Array.isArray(row.eventTypes) ? row.eventTypes : (row.eventTypes || '').split(',').map((e: string) => e.trim()).filter(Boolean);
                  if (isEditing) {
                    return (
                      <div className="flex flex-col gap-1 max-h-32 overflow-y-auto border border-[var(--border)] p-2 rounded text-xs bg-black/5">
                        <label className="flex items-center gap-2 cursor-pointer hover:text-[var(--text-primary)]">
                          <input
                            type="checkbox"
                            checked={currentEvents.includes('*')}
                            onChange={(e) => {
                              if (e.target.checked) onChange?.('*');
                              else onChange?.('');
                            }}
                          />
                          {tDev('allEvents')}
                        </label>
                        {availableEvents.map(e => (
                          <label key={e} className="flex items-center gap-2 cursor-pointer hover:text-[var(--text-primary)]">
                            <input
                              type="checkbox"
                              checked={currentEvents.includes(e)}
                              onChange={(ev) => {
                                const newEvents = ev.target.checked
                                  ? [...currentEvents.filter((c: string) => c !== '*'), e]
                                  : currentEvents.filter((c: string) => c !== e && c !== '*');
                                onChange?.(newEvents.join(', '));
                              }}
                            />
                            {e}
                          </label>
                        ))}
                      </div>
                    );
                  }
                  return (
                    <div className="flex flex-wrap gap-1">
                      {currentEvents.map((e: string) => (
                        <span key={e} className="inline-block bg-black/20 px-2 py-0.5 rounded text-xs">{e.trim()}</span>
                      ))}
                    </div>
                  );
                }
              },
              {
                key: 'secretKey',
                title: tDev('secretKey'),
                type: 'text',
                disabled: true,
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                render: (row: any) => <span className="font-mono text-xs">{row.secretKey}</span>
              }
            ]}
          />
        </div>
      </div>
    </DetailsLayout>
  );
}

