    inventoryControllerFindAllLocations: () => mockSdkFetch('/locations'),
    taxCategoriesControllerFindAll: () => mockSdkFetch('/tax-categories'),
    ordersControllerUpdate: (...args: any[]) => mockSdkMutate('update', ...args),
