                lineNumber: 1,
                productId: 'prod-1',
                productNumber: 'WDG-001',
                productDescription: 'Widget',
                quantity: '10',
                pricePerUnit: '50.00',
                discountPercentage: '0',
                amount: '500.00',
                taxCategoryId: null,
                tax: '50.00',
                totalAmount: '550.00',
