describe('useOrder — mutations', () => {
    beforeEach(() => {
        jest.clearAllMocks();
        setupMocks(makeOrder());
    });

    it('saveHeader calls PATCH with correct body', async () => {
        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());

        // Simulate header edit to make it dirty
        act(() => result.current.setEditName('New Name'));
        await waitFor(() => expect(result.current.headerDirty).toBe(true));

        await act(async () => { await result.current.saveHeader(); });

        expect(mockSdkMutate).toHaveBeenCalledWith(
            'update',
            'so-001',
            expect.objectContaining({ name: 'New Name' }),
        );
    });

    it('changeState calls PATCH with stateCode', async () => {
        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());
 
        await act(async () => { await result.current.changeState(SALES_ORDER_STATE.QUOTED); });
 
        expect(mockSdkMutate).toHaveBeenCalledWith(
            'changeState',
            'so-001',
            expect.objectContaining({ stateCode: SALES_ORDER_STATE.QUOTED }),
        );
    });

    it('updateLine calls PATCH on the correct endpoint', async () => {
        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());

        await act(async () => { await result.current.updateLine('line-1', 'quantity', '20'); });

        expect(mockSdkMutate).toHaveBeenCalledWith(
            'updateLine',
            'so-001',
            'line-1',
            { quantity: '20' },
        );
    });

    it('copyOrder calls POST and navigates to new order', async () => {
        mockSdkMutate.mockImplementation(async (action) => {
            if (action === 'create') return { data: { salesOrderId: 'so-002' } };
            return {};
        });

        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());

        await act(async () => { await result.current.copyOrder(); });

        expect(mockSdkMutate).toHaveBeenCalledWith(
            'create',
            expect.objectContaining({
                name: 'Copy of Test Order',
                customerId: 'cust-1',
                lines: expect.arrayContaining([
                    expect.objectContaining({ productId: 'prod-1', quantity: '10' }),
                ]),
            }),
        );
        expect(mockPush).toHaveBeenCalledWith('/sales-orders/so-002');
    });

    it('archiveOrder calls POST after confirm', async () => {
        jest.spyOn(window, 'confirm').mockReturnValue(true);

        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());

        await act(async () => { await result.current.archiveOrder(); });

        expect(mockSdkMutate).toHaveBeenCalledWith(
            'archive',
            'so-001',
            { body: {} }
        );

        jest.restoreAllMocks();
    });

    it('archiveOrder does nothing when confirm is cancelled', async () => {
        jest.spyOn(window, 'confirm').mockReturnValue(false);

        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());
        mockSdkMutate.mockClear();

        await act(async () => { await result.current.archiveOrder(); });

        expect(mockSdkMutate).not.toHaveBeenCalled();
        jest.restoreAllMocks();
    });

    it('unarchiveOrder calls POST', async () => {
        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());

        await act(async () => { await result.current.unarchiveOrder(); });

        expect(mockSdkMutate).toHaveBeenCalledWith(
            'unarchive',
            'so-001',
            { body: {} }
        );
    });

    it('removeLine calls DELETE after confirm', async () => {
        jest.spyOn(window, 'confirm').mockReturnValue(true);

        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());

        await act(async () => { await result.current.removeLine('line-1'); });

        expect(mockSdkMutate).toHaveBeenCalledWith(
            'removeLine',
            'so-001',
            'line-1'
        );

        jest.restoreAllMocks();
    });

    it('removeLine does nothing when confirm is cancelled', async () => {
        jest.spyOn(window, 'confirm').mockReturnValue(false);

        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());
        mockSdkMutate.mockClear();

        await act(async () => { await result.current.removeLine('line-1'); });

        expect(mockSdkMutate).not.toHaveBeenCalled();
        jest.restoreAllMocks();
    });

    it('addLineFromProduct calls POST with product data', async () => {
        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());

        const product = {
            productId: 'prod-new',
            productNumber: 'NEW-001',
            name: 'New Product',
            listPrice: '75.00',
            tradePrice: '70.00',
        };

        await act(async () => { await result.current.addLineFromProduct(product as unknown as import('@modbm/sdk').ProductResponseDto); });

        expect(mockSdkMutate).toHaveBeenCalledWith(
            'addLine',
            'so-001',
            expect.objectContaining({
                productId: 'prod-new',
                productDescription: 'New Product',
                quantity: '1',
                pricePerUnit: '75.00',
            }),
        );
    });

    it('addLineFromProduct rejects duplicates with toast error', async () => {
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        const { toast } = require('react-hot-toast');

        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());
        mockSdkMutate.mockClear();

        // prod-1 is already in the order lines
        const duplicate = {
            productId: 'prod-1',
            productNumber: 'WDG-001',
            name: 'Widget',
            listPrice: '50.00',
        };

        await act(async () => { await result.current.addLineFromProduct(duplicate as unknown as import('@modbm/sdk').ProductResponseDto); });

        expect(mockSdkMutate).not.toHaveBeenCalled();
        expect(toast).toHaveBeenCalled();
    });

    it('saveHeader sets error on failure', async () => {
        const { result } = renderHook(() => useOrder('so-001'));
        await waitFor(() => expect(result.current.order).toBeTruthy());

        act(() => result.current.setEditName('Changed'));
        await waitFor(() => expect(result.current.headerDirty).toBe(true));

        mockSdkMutate.mockRejectedValueOnce(new Error('Network error'));
        await act(async () => { await result.current.saveHeader(); });

        expect(result.current.error).toBe('Network error');
    });
});

'use client';

import React, { useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { useSearchParams, useRouter } from 'next/navigation';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { usePersistedFilter } from '@/hooks/usePersistedFilter';
import DataGrid from '@/components/DataGrid';
import { formatAmount } from '@/lib/currency';
import { useSettings } from '@/components/SettingsProvider';

export default function GlobalPurchaseInvoicesPage() {
    const { baseCurrency } = useSettings();
    const t = useTranslations('purchaseOrders');
    const tCommon = useTranslations('common');
    const tStates = useTranslations('common.states');
    useDocumentTitle(t('supplierInvoicesCardHeading'));
    const searchParams = useSearchParams();
    const router = useRouter();
    const invoiceFilter = searchParams.get('invoiceId') || '';
    const [days, setDays, isReady] = usePersistedFilter('supplier-invoices-days', '90');

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const handleRowClicked = useCallback((row: any) => {
        if (row.invoiceId) {
            router.push(`/supplier-invoices/${row.invoiceId}`);
        }
    }, [router]);

    // When filtering by specific invoiceId, pass it to the API (server skips date range)
    const gridEndpoint = !isReady ? undefined : (invoiceFilter
        ? `/api/purchase-invoices?invoiceId=${encodeURIComponent(invoiceFilter)}&limit=0`
        : `/api/purchase-invoices?days=${days}&limit=0`);

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const gridColumns: any[] = [
        { field: 'invoiceId', headerName: 'ID', hide: true },
        { field: 'invoiceNumber', headerName: t('columns.invoiceNumber'), width: 180 },
        { field: 'supplierInvoiceNumber', headerName: t('columns.supplierInvoiceNumber'), width: 220 },
        { field: 'vendorName', headerName: t('columns.vendor'), width: 250 },
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        { field: 'createdOn', headerName: t('columns.date'), width: 200, valueFormatter: (p: import("ag-grid-community").ICellRendererParams<any>) => p.value ? new Date(p.value as string | number).toLocaleDateString() : '' },
        { 
            field: 'totalAmount', 
            headerName: t('columns.amount'), 
            type: 'numericColumn', 
            width: 150,
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            valueGetter: (params: import("ag-grid-community").ValueFormatterParams<any>) => {
                if (!params.data?.totalAmount) return null;
                return parseFloat(params.data.totalAmount);
            },
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            valueFormatter: (params: import("ag-grid-community").ValueFormatterParams<any>) => {
                if (!params.value || params.value === 0) return '—';
                return formatAmount(params.value, params.data?.currencyCode || baseCurrency);
            },
        },
        { 
            field: 'stateCode', 
            headerName: t('columns.state'), 
            width: 140,
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            valueFormatter: (params: import("ag-grid-community").ValueFormatterParams<any>) => {
                if (!params.value) return '';
                const s = String(params.value).toLowerCase();
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                return tStates.has(s as any) ? tStates(s as any) : String(params.value);
            }
        },
    ];

    return (
        <DataGrid 
            endpoint={gridEndpoint} 
            columns={gridColumns} 
            gridKey="global-purchase-invoices"
            rowIdField="invoiceId"
            onRowClicked={handleRowClicked}
            pageTitle={t('supplierInvoicesCardHeading')}
            headerFilters={
                <select
                    value={days}
                    onChange={(e) => setDays(e.target.value)}
                    className="input text-sm"
                    style={{ minWidth: 150 }}
                >
                    <option value="30">{tCommon('filters.last30Days')}</option>
                    <option value="90">{tCommon('filters.last90Days')}</option>
                    <option value="365">{tCommon('filters.last1Year')}</option>
                    <option value="0">{tCommon('filters.allTime')}</option>
                </select>
            }
            headerActions={
                <button
                    className="btn btn-primary whitespace-nowrap ml-2 lg:ml-0"
                    onClick={() => router.push('/supplier-invoices/new')}
                >
                    {t('buttons.enterSupplierBill')}
                </button>
            }
        />
    );
}

